#include "mqtt_runtime.cpp"
#include "button_read.cpp"

// Run the actual publisher using a deterministic clock, GPIO levels and MQTT queue.
static void advance(uint32_t duration) {
  for (uint32_t elapsed = 0; elapsed < duration; elapsed += 10) {
    tick += 10;
    handleSauluxMqttInputs();
  }
}
static void reset(uint32_t start = 0) {
  tick = lastInputPoll = start;
  client = TestMqtt{};
  mqtt = &client;
  mqttEnabled = buttonPublishMqtt = true;
  std::strcpy(mqttDeviceTopic, "saulux/test");
  inputTopic[0] = '\0';
  refreshInputs.store(true);
  levels.clear(); buttons.clear();
  for (uint8_t i = 0; i < INPUT_COUNT; i++) {
    inputStates[i] = InputState{};
    buttons.push_back({int8_t(4 + i), BTN_TYPE_PUSH});
    levels[4 + i] = HIGH;
  }
}
static void checkSnapshot(const char* prefix = "saulux/test") {
  assert(client.messages.size() == INPUT_COUNT);
  for (uint8_t i = 0; i < INPUT_COUNT; i++) {
    const auto& message = client.messages[i];
    assert(message.topic == std::string(prefix) + "/input/" + std::to_string(i + 1) + "/state");
    assert(message.qos == 1 && message.retain);
    assert(message.payload == (isButtonPressed(i) ? "1" : "0"));
  }
}
int main() {
  assert(INPUT_COUNT == (SAULUX_MODEL == 2 ? 5 : SAULUX_MODEL == 4 ? 1 : 2));
  reset();
  onSauluxMqttConnect();
  assert(client.messages.empty()); // callback only signals the main loop
  advance(50); assert(client.messages.empty());
  advance(10); checkSnapshot();
  client.messages.clear(); advance(1000); assert(client.messages.empty());
  // Neither short electrical glitches nor bouncing edges become published presses.
  levels[4] = LOW; advance(40); assert(client.messages.empty());
  levels[4] = HIGH; advance(10);
  levels[4] = LOW; advance(10); advance(40); assert(client.messages.empty());
  advance(10);
  assert(client.messages.size() == 1 && client.messages.back().payload == "1");
  advance(700); assert(client.messages.size() == 1); // no long-press repetition in state topics
  levels[4] = HIGH; advance(60);
  assert(client.messages.size() == 2 && client.messages.back().payload == "0");

  // Reconnect sends current values for every port, including a button held while offline.
  client.messages.clear(); client.online = false;
  levels[4] = LOW; advance(100); assert(client.messages.empty());
  client.online = true; onSauluxMqttConnect(); advance(10); checkSnapshot();
  client.messages.clear(); onSauluxMqttConnect(); advance(10); checkSnapshot();

  // Logical state honors active-HIGH buttons as well as the default active-LOW wiring.
  reset(); buttons[0].type = BTN_TYPE_PUSH_ACT_HIGH; levels[4] = LOW;
  advance(60); checkSnapshot(); client.messages.clear();
  levels[4] = HIGH; advance(60);
  assert(client.messages.size() == 1 && client.messages[0].payload == "1");

  // Disabled publishing and unused/analog ports remove retained states instead of leaving stale values.
  reset(); advance(60); client.messages.clear();
  buttonPublishMqtt = false; advance(10);
  assert(client.messages.size() == INPUT_COUNT);
  for (const auto& message : client.messages) assert(message.payload.empty() && message.retain);
  client.messages.clear(); levels[4] = LOW; advance(100); assert(client.messages.empty());
  buttonPublishMqtt = true; advance(60); checkSnapshot(); client.messages.clear();
  buttons.back().type = BTN_TYPE_ANALOG; advance(10);
  assert(client.messages.size() == 1 && client.messages[0].payload.empty());
  client.messages.clear(); advance(100); assert(client.messages.empty());

  // Changing the device topic refreshes every state without waiting for a physical edge.
  reset(); advance(60); client.messages.clear();
  std::memset(mqttDeviceTopic, 'a', MQTT_MAX_TOPIC_LEN);
  mqttDeviceTopic[MQTT_MAX_TOPIC_LEN] = '\0';
  advance(10); checkSnapshot(mqttDeviceTopic);

  // Queue rejection is retried at bounded intervals, then the latest state is announced once.
  reset(); client.accepting = false; advance(60);
  assert(client.attempts == INPUT_COUNT && client.messages.empty());
  advance(240); assert(client.attempts == INPUT_COUNT);
  advance(10); assert(client.attempts == 2 * INPUT_COUNT);
  client.accepting = true; advance(250); checkSnapshot();
  const auto attempts = client.attempts;
  advance(500); assert(client.attempts == attempts);

  reset(); mqttEnabled = false; advance(100); assert(client.attempts == 0);
  mqttEnabled = true; mqttDeviceTopic[0] = '\0'; advance(100); assert(client.attempts == 0);
  reset(UINT32_MAX - 15); advance(60); checkSnapshot(); // millis wrap-around
  std::puts("MQTT input snapshots, edges, debounce, reconnect, disabling and retries passed");
}
